-- 122K quarterly call-report records for federally insured credit unions -- the financial vitals, 1994 to present.
-- Auto-generated by scripts/gen_evidence_pages.py: 121,713 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("CYCLE_DATE") as year, count(*) as records
from THE_LIBRARY.MONEY.CREDIT_UNION_CALL_REPORTS
where "CYCLE_DATE" is not null
group by 1
order by 1
